// =============================================================================
// SECURITY FIX (SEC-008): AI Prompt Injection Protection
// =============================================================================
// Detects and blocks prompt injection attempts before they reach the LLM.
// Patterns detected:
// 1. Instruction overrides ("ignore previous", "new instructions")
// 2. Role manipulation ("you are now", "act as")
// 3. System prompt leakage attempts ("repeat your instructions")
// 4. Delimiter injection (multiple newlines, special chars)
// =============================================================================

const userText = ($json.text || $json.message?.text || '').toString().trim();

if (!userText || userText.length === 0) {
  return {
    json: {
      is_safe: false,
      blocked: true,
      reason: 'empty_input',
      sanitized_text: ''
    }
  };
}

// Normalize for detection (lowercase, remove extra spaces)
const normalized = userText.toLowerCase().replace(/\s+/g, ' ');

// Injection patterns (case-insensitive)
const injectionPatterns = [
  // Instruction overrides
  /ignore (all |previous |prior |above )?instructions?/i,
  /disregard (all |previous |prior )?instructions?/i,
  /forget (all |previous |everything )?instructions?/i,
  /new instructions?:/i,
  /system (prompt|message|instructions?):/i,

  // Role manipulation
  /(you are|you're) now (a |an )?(?!hungry|tired|welcome)/i, // Allow "you're now hungry" etc.
  /act as (a |an )?(?!waiter|server|assistant)/i, // Allow "act as waiter"
  /pretend (you are|you're|to be)/i,
  /roleplay as/i,

  // System prompt leakage
  /repeat (your |the )?instructions?/i,
  /what (are |is )?(your |the )?instructions?/i,
  /show me (your |the )?(prompt|instructions?|rules?)/i,
  /print (your |the )?(system |original )?(prompt|instructions?)/i,

  // Delimiter injection
  /={5,}/,  // 5+ equals signs
  /-{5,}/,  // 5+ dashes
  /\n{4,}/, // 4+ newlines
  /<\/?system>/i,
  /<\/?user>/i,
  /<\/?assistant>/i,

  // Encoding tricks
  /base64|hex|rot13|decode/i,

  // Jailbreak attempts
  /(developer mode|admin mode|debug mode|god mode)/i,
  /sudo /i,
  /execute.*command/i
];

// Check for injection patterns
let isInjection = false;
let matchedPattern = null;

for (const pattern of injectionPatterns) {
  if (pattern.test(normalized)) {
    isInjection = true;
    matchedPattern = pattern.toString();
    break;
  }
}

// Length check (suspiciously long inputs)
const maxLength = parseInt($env.AI_INPUT_MAX_LENGTH || '500', 10);
const tooLong = userText.length > maxLength;

// Sanitize text (remove excessive whitespace, control chars)
const sanitized = userText
  .replace(/[\x00-\x1F\x7F-\x9F]/g, '') // Remove control characters
  .replace(/\s+/g, ' ') // Collapse multiple spaces
  .trim()
  .slice(0, maxLength); // Enforce max length

// Decision
const isSafe = !isInjection && !tooLong && sanitized.length > 0;
const blocked = !isSafe;

let reason = 'ok';
if (isInjection) reason = 'injection_detected';
else if (tooLong) reason = 'input_too_long';
else if (sanitized.length === 0) reason = 'empty_after_sanitization';

return {
  json: {
    is_safe: isSafe,
    blocked,
    reason,
    matched_pattern: matchedPattern || null,
    original_text: userText,
    sanitized_text: sanitized,
    original_length: userText.length,
    sanitized_length: sanitized.length,
    _security: {
      injection_check_passed: !isInjection,
      length_check_passed: !tooLong,
      timestamp: new Date().toISOString()
    },
    // Pass through other data
    restaurantId: $json.restaurantId || $json.restaurant_id,
    tenant_context: $json.tenant_context
  }
};

// Blocked - return safe error message
return {
  json: {
    response: "🛡️ Désolé, votre message contient des caractères ou patterns non autorisés. Veuillez reformuler votre demande de manière simple.",
    blocked: true,
    reason: $json.reason || 'security_check_failed',
    _security_block: true
  }
};

// SECURITY: Use sanitized text from guardrails, not raw user input
const sanitizedInput = $node['Detect & Block Prompt Injection (AI Guardrails)'].json;
const userText = sanitizedInput.sanitized_text; // Already sanitized and validated

const menu = $input.item(0).json;
const brandRaw = $input.item(1).json;
const brand = Array.isArray(brandRaw) ? brandRaw[0] : (brandRaw.data?.[0]?.attributes || brandRaw);

// Language detection (Darija patterns)
const darijaPatterns = /\b(sahit|bsaha|chhal|wesh|khouya|rabbi|bghit|3andi)\b/i;
const arabicPattern = /[\u0600-\u06FF]/;
const detectedLang = arabicPattern.test(userText) ? 'ar' : (darijaPatterns.test(userText) ? 'dz' : 'fr');

return {
  json: {
    user_text: userText,
    menu: menu.menu_formatted,
    menu_index: menu.menu_index,
    brand: brand,
    detected_lang: detectedLang,
    _security: {
      input_sanitized: true,
      injection_check_passed: true
    }
  }
};

// Extract response from Ollama format
const ollamaResponse = $input.first().json;
const content = ollamaResponse.message?.content || ollamaResponse.response || '';

// Remove XML tags if LLM echoed them back
const cleanedContent = content.replace(/<\/?user_query>/g, '').trim();

return {
  json: {
    response: cleanedContent,
    model: ollamaResponse.model,
    done: ollamaResponse.done,
    _security: {
      ai_guardrails_applied: true,
      prompt_injection_protected: true
    }
  }
};
